struct PolicyDecisionPoint {
    virtual bool allowed(const Subject&, const Action&, const Resource&) const = 0;
};

template <class Handler>
struct Enforced {                                  /* the enforcement point wraps the handler */
    const PolicyDecisionPoint& pdp;
    Handler next;
    std::optional<Response> operator()(const Request& r) const {
        if (!pdp.allowed(r.subject, r.action, r.resource))
            return Response::forbidden();          /* 403, handler never runs */
        return next(r);
    }
};

